import { InspectorCore } from "./InspectorCore";
import type {
  ConversationEventAction,
  HttpAuth,
  LogErrorFn,
  OnboardingTooltipConfig,
  ShowToastFn,
  UpdateToastFn,
  DismissToastFn,
  IsToastVisibleFn,
  TrackFn,
} from "../types";

export type InspectorProps = {
  projectUrl: string;
  botDataEndpoint: string;
  httpAuth?: HttpAuth;
  conversationEventActions?: ConversationEventAction[];
  projectId?: string;
  singleSessionMode?: boolean;
  isEmbedded?: boolean;
  inspectMode?: boolean;
  initialInspectMode?: boolean;
  onSessionStart?: (sessionId: string) => void;
  onInspectModeChange?: (inspectMode: boolean) => void;
  onMessageSent?: (message: string) => void;
  onReconnectError?: (error: unknown) => void;
  track?: TrackFn;
  logError?: LogErrorFn;
  showToast?: ShowToastFn;
  updateToast?: UpdateToastFn;
  dismissToast?: DismissToastFn;
  isToastVisible?: IsToastVisibleFn;
  onboardingTooltips?: OnboardingTooltipConfig[];
  voiceFeaturesEnabled?: boolean;
  socketReconnectAttempts?: number;
  sessionId?: string;
  resetSession?: () => void;
  trackerEndpoint?: string;
  channel?: string;
  socketEndpoint?: string;
  socketAuth?: Record<string, string>;
};

/** Public API — for embedding in a host app. */
export const Inspector = ({ isEmbedded = true, ...props }: InspectorProps) => (
  <InspectorCore {...props} isEmbedded={isEmbedded} />
);
